namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatings { get; set; }
    public int RatingSum { get; set; }

    public double AverageRating => TotalRatings == 0 ? 0 : (double)RatingSum / TotalRatings;
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple and delicious pizza with fresh basil and mozzarella.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = ["Preheat oven to 475°F (245°C).", "Roll out the dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
                TotalRatings = 12, RatingSum = 52
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with pancetta off heat.", "Add egg mixture and toss quickly to coat.", "Serve immediately with extra cheese."],
                TotalRatings = 8, RatingSum = 38
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken in a rich, spiced tomato cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or broil chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and garam masala.", "Add chicken and simmer 10 minutes."],
                TotalRatings = 15, RatingSum = 70
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "A vibrant stir-fried noodle dish with vegetables and peanuts.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Green onions", "Peanuts", "Lime", "Tamarind paste", "Fish sauce", "Sugar"],
                Steps = ["Soak rice noodles in warm water 20 minutes.", "Press and cube tofu, then pan-fry until golden.", "Make sauce: mix tamarind, fish sauce, and sugar.", "Stir-fry vegetables briefly.", "Add noodles and sauce, toss to combine.", "Serve topped with peanuts, lime, and green onions."],
                TotalRatings = 6, RatingSum = 26
            },
            new Recipe
            {
                Id = 5, Title = "Guacamole", Category = "Mexican",
                Description = "Fresh and zesty avocado dip, perfect as a starter.",
                Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
                Steps = ["Halve and pit avocados, scoop into a bowl.", "Mash to desired consistency.", "Dice onion, tomato, and jalapeño.", "Mix everything together with lime juice.", "Season with salt to taste.", "Serve immediately with tortilla chips."],
                TotalRatings = 10, RatingSum = 43
            },
            new Recipe
            {
                Id = 6, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in warm tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheese", "Sour cream", "Salsa"],
                Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer.", "Warm tortillas in a dry pan.", "Assemble tacos with beef and toppings.", "Squeeze lime over top.", "Serve with salsa and sour cream."],
                TotalRatings = 9, RatingSum = 40
            },
            new Recipe
            {
                Id = 7, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual chocolate cakes with a molten center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = ["Preheat oven to 425°F (220°C).", "Melt chocolate and butter together.", "Whisk in eggs, sugar, and vanilla.", "Fold in flour gently.", "Pour into greased ramekins.", "Bake 12-14 minutes until edges are set but center jiggles."],
                TotalRatings = 20, RatingSum = 95
            },
            new Recipe
            {
                Id = 8, Title = "Miso Soup", Category = "Asian",
                Description = "A light and savory Japanese soup with tofu and seaweed.",
                Ingredients = ["Dashi stock", "White miso paste", "Silken tofu", "Wakame seaweed", "Green onions"],
                Steps = ["Bring dashi stock to a gentle simmer.", "Rehydrate wakame in water.", "Cube tofu into small pieces.", "Dissolve miso paste into the broth (do not boil).", "Add tofu and wakame.", "Garnish with sliced green onions."],
                TotalRatings = 5, RatingSum = 21
            },
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.TotalRatings++;
            recipe.RatingSum += stars;
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title.Trim(),
            Category = submission.Category.Trim(),
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

