arguments.new_str:
@page "/"

<PageTitle>RecipeHub - Home</PageTitle>

<h1>Welcome to RecipeHub 🍽️</h1>
<p class="lead">Discover, share, and rate delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var cat in Categories)
    {
        <div class="col-md-3 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h3>@GetEmoji(cat)</h3>
                    <h5 class="card-title">@cat</h5>
                    <a href="@($"categories/{cat}")" class="btn btn-outline-primary btn-sm mt-2">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private static string GetEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Asian" => "🥢",
        "Mexican" => "🌮",
        "Desserts" => "🍰",
        _ => "🍴"
    };
}

arguments.file_text:
@page "/categories"

<PageTitle>Browse Recipes - RecipeHub</PageTitle>

<h1>Browse Recipes</h1>
<p>Choose a category to explore recipes.</p>

<div class="list-group mt-3" style="max-width: 400px;">
    @foreach (var cat in Categories)
    {
        <a href="@($"categories/{cat}")" class="list-group-item list-group-item-action">
            @cat (@RecipeService.GetByCategory(cat).Count recipes)
        </a>
    }
</div>

@code {
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<string> Categories = [];

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }
}

@page "/categories/{CategoryName}"

<PageTitle>@CategoryName Recipes - RecipeHub</PageTitle>

<h1>@CategoryName Recipes</h1>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="categories">All Categories</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">No recipes found in this category.</div>
}
else
{
    <div class="row">
        @foreach (var recipe in Recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Description</p>
                        <p class="mb-1">
                            <small>
                                @if (recipe.TotalRatings > 0)
                                {
                                    <span>⭐ @recipe.AverageRating.ToString("F1") (@recipe.TotalRatings ratings)</span>
                                }
                                else
                                {
                                    <span class="text-muted">No ratings yet</span>
                                }
                            </small>
                        </p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-primary btn-sm mt-2">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private IReadOnlyList<RecipeHub.Models.Recipe> Recipes = [];

    protected override void OnInitialized()
    {
        Recipes = RecipeService.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeHub</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="categories">Categories</a></li>
            <li class="breadcrumb-item"><a href="@($"categories/{Recipe.Category}")">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <h1>@Recipe.Title</h1>
    <p class="lead text-muted">@Recipe.Description</p>

    <div class="row mt-4">
        <div class="col-md-4">
            <div class="card mb-4">
                <div class="card-header"><strong>Ingredients</strong></div>
                <ul class="list-group list-group-flush">
                    @foreach (var item in Recipe.Ingredients)
                    {
                        <li class="list-group-item">@item</li>
                    }
                </ul>
            </div>
        </div>

        <div class="col-md-8">
            <h4>Instructions</h4>
            <ol class="list-group list-group-numbered mb-4">
                @foreach (var step in Recipe.Steps)
                {
                    <li class="list-group-item">@step</li>
                }
            </ol>
        </div>
    </div>

    <div class="card mt-2 mb-4" style="max-width: 400px;">
        <div class="card-body">
            <h5 class="card-title">Rate this Recipe</h5>
            @if (Recipe.TotalRatings > 0)
            {
                <p class="mb-2">Average: ⭐ @Recipe.AverageRating.ToString("F1") (@Recipe.TotalRatings ratings)</p>
            }
            <StarRating RecipeId="Recipe.Id" @rendermode="InteractiveServer" />
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Models.Recipe? Recipe;

    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer

<div>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span
            @onclick="() => SubmitRating(star)"
            style="cursor: pointer; font-size: 1.5rem;"
            role="button"
            title="@($"Rate {star} star{(star > 1 ? "s" : "")}")">
            @(star <= SelectedStars ? "★" : "☆")
        </span>
    }

    @if (Submitted)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int SelectedStars;
    private bool Submitted;

    private void SubmitRating(int stars)
    {
        SelectedStars = stars;
        RecipeService.AddRating(RecipeId, stars);
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (SubmittedRecipe is not null)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong>
        <a href="@($"recipe/{SubmittedRecipe.Id}")">View "@SubmittedRecipe.Title"</a>
    </div>
}

<EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm" class="mt-3" style="max-width: 600px;">
    <DataAnnotationsValidator />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="Submission.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="Submission.Category" class="form-select">
            <option value="">-- Select a category --</option>
            <option value="Italian">Italian</option>
            <option value="Indian">Indian</option>
            <option value="Asian">Asian</option>
            <option value="Mexican">Mexican</option>
            <option value="Desserts">Desserts</option>
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients (one per line)</label>
        <InputTextArea id="ingredients" @bind-Value="Submission.Ingredients" class="form-control" rows="5"
            placeholder="2 cups flour&#10;1 cup sugar&#10;3 apples, sliced" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps (one per line)</label>
        <InputTextArea id="steps" @bind-Value="Submission.Steps" class="form-control" rows="5"
            placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Add wet ingredients." />
    </div>

    <button type="submit" class="btn btn-primary"
        disabled="@(string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))">
        Submit Recipe
    </button>
</EditForm>

@code {
    [Inject] public RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private RecipeHub.Models.RecipeSubmission Submission { get; set; } = new();
    private RecipeHub.Models.Recipe? SubmittedRecipe;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Submission.Title) || string.IsNullOrWhiteSpace(Submission.Category))
            return;

        SubmittedRecipe = RecipeService.AddRecipe(Submission);
        Submission = new();
    }
}

